const mount=document.querySelector('#viewport'),renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputEncoding=THREE.sRGBEncoding;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;mount.append(renderer.domElement);
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(33,1,.01,60);let yaw=-.25,pitch=.14,distance=4.7;const target=new THREE.Vector3(0,.94,0);
scene.add(new THREE.HemisphereLight(0xfff7de,0x7a9682,.7));const key=new THREE.DirectionalLight(0xfff3de,1.7);key.position.set(-3,5,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-3;key.shadow.camera.right=3;key.shadow.camera.top=3;key.shadow.camera.bottom=-3;key.shadow.normalBias=.015;scene.add(key);const rim=new THREE.DirectionalLight(0xd9edff,.8);rim.position.set(2,3,-2);scene.add(rim);
