let actor,mixer,active,paused=false,helper,blocking=false;const actions={},buttons={};const labels={Idle:'Repos',Walk:'Marche',Run:'Course',Jump:'Saut',Dodge_Back:'Esquive',Hit_React:'Impact',Combat_Idle:'Garde',Sword_Slash:'Taille',Sword_Backslash:'Revers',Sword_Overhead:'Coup vertical',Sword_Thrust:'Estoc',Shield_Raise:'Lever',Shield_Hold:'Protéger',Shield_Hit:'Blocage',Shield_Lower:'Baisser'};const loops=new Set(['Idle','Walk','Run','Combat_Idle','Shield_Hold']);
function play(name,fade=.14){if(!actions[name])return;const next=actions[name];if(active&&active!==next)active.fadeOut(fade);next.reset().setEffectiveWeight(1).setEffectiveTimeScale(1).fadeIn(fade).play();next.setLoop(loops.has(name)?THREE.LoopRepeat:THREE.LoopOnce,Infinity);next.clampWhenFinished=true;active=next;document.querySelector('#current').textContent=labels[name]||name;for(const [n,b]of Object.entries(buttons))b.setAttribute('aria-pressed',String(n===name));if(paused)mixer.update(fade+.001);}
for(const [name,label]of Object.entries(labels)){const b=document.createElement('button');b.textContent=label;b.dataset.clip=name;b.setAttribute('aria-pressed','false');b.disabled=true;b.onclick=()=>play(name);buttons[name]=b;document.querySelector(['Idle','Walk','Run','Jump','Dodge_Back','Hit_React'].includes(name)?'#locomotion':'#combat').append(b);}
new THREE.GLTFLoader().load('assets/aerin.glb',g=>{actor=g.scene;scene.add(actor);actor.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;o.frustumCulled=false;}});mixer=new THREE.AnimationMixer(actor);for(const clip of g.animations)actions[clip.name]=mixer.clipAction(clip);helper=new THREE.SkeletonHelper(actor);helper.material.depthTest=false;helper.renderOrder=10;helper.visible=false;scene.add(helper);mixer.addEventListener('finished',e=>{if(e.action!==active)return;const n=e.action.getClip().name;if(n==='Shield_Raise'||n==='Shield_Hit')play('Shield_Hold');else play('Combat_Idle');});for(const b of Object.values(buttons))b.disabled=false;document.querySelector('#loading').hidden=true;play('Combat_Idle',0);mixer.update(0);window.hero={scene,actor,mixer,actions,play,helper,renderer,camera};},undefined,e=>{document.querySelector('#loading').textContent='Chargement impossible';document.querySelector('#error').textContent='Ouvre cet aperçu avec le serveur local décrit dans le README.';console.error(e);});
function resize(){const r=mount.getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(mount);
function cameraUpdate(){camera.position.set(Math.sin(yaw)*Math.cos(pitch)*distance,target.y+Math.sin(pitch)*distance,Math.cos(yaw)*Math.cos(pitch)*distance);camera.lookAt(target);}
let drag=null;mount.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];mount.setPointerCapture(e.pointerId);});mount.addEventListener('pointermove',e=>{if(!drag)return;yaw-=(e.clientX-drag[0])*.008;pitch=THREE.MathUtils.clamp(pitch+(e.clientY-drag[1])*.005,-.1,.65);drag=[e.clientX,e.clientY];});for(const n of ['pointerup','pointercancel','lostpointercapture'])mount.addEventListener(n,()=>drag=null);mount.addEventListener('wheel',e=>{e.preventDefault();distance=THREE.MathUtils.clamp(distance+e.deltaY*.003,2.7,7);},{passive:false});
document.querySelector('#speed').oninput=e=>{document.querySelector('#speedValue').textContent=e.target.value+'×';};document.querySelector('#pause').onclick=e=>{paused=!paused;e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'Reprendre':'Pause';};document.querySelector('#bones').onclick=e=>{if(!helper)return;helper.visible=!helper.visible;e.currentTarget.setAttribute('aria-pressed',String(helper.visible));};
window.addEventListener('keydown',e=>{if(e.repeat||/INPUT|BUTTON|A/.test(e.target.tagName))return;const map={Digit1:'Sword_Slash',Digit2:'Sword_Backslash',Digit3:'Sword_Overhead',Digit4:'Sword_Thrust',Space:'Jump',KeyE:'Dodge_Back'};if(map[e.code]){e.preventDefault();play(map[e.code]);}if(e.code==='KeyB'&&!blocking){blocking=true;play('Shield_Raise');}});window.addEventListener('keyup',e=>{if(e.code==='KeyB'){blocking=false;play('Shield_Lower');}});window.addEventListener('blur',()=>{if(blocking){blocking=false;play('Shield_Lower');}drag=null;});
const clock=new THREE.Clock();renderer.setAnimationLoop(()=>{const dt=Math.min(clock.getDelta(),.05);if(mixer&&!paused)mixer.update(dt*Number(document.querySelector('#speed').value));cameraUpdate();renderer.render(scene,camera);});
